document.addEventListener("DOMContentLoaded",()=>{const navbar=document.querySelector('.navbar'),stickyTrigger=document.querySelector('.logo-img')?.offsetHeight||50;navbar&&window.addEventListener('scroll',()=>navbar.classList.toggle('sticky',window.pageYOffset>stickyTrigger));setTimeout(()=>{document.querySelectorAll(".alert").forEach(alert=>{alert.style.transition="opacity 0.5s";alert.style.opacity="0";setTimeout(()=>alert.remove(),500)})},5000);document.addEventListener('contextmenu',e=>e.preventDefault());document.querySelectorAll('img').forEach(img=>img.addEventListener('dragstart',e=>e.preventDefault()));document.querySelectorAll(".gallery-img").forEach(img=>{img.onload=()=>requestAnimationFrame(()=>img.classList.add("loaded"));});const cookieBanner=document.getElementById('cookie-banner');cookieBanner&&localStorage.getItem('cookiesAccepted')==='true'&&(cookieBanner.style.display='none');window.acceptCookies=()=>{localStorage.setItem('cookiesAccepted','true');cookieBanner&&(cookieBanner.style.display='none');};let images=[],currentIndex=0;window.openImageModal=(e,imageSrc)=>{e.preventDefault();const modalElement=document.getElementById("imageModal"),modalImage=document.getElementById("modalImage");if(!modalElement||!modalImage)return console.error("⚠️ Modale o immagine non trovati!");const galleryImages=document.querySelectorAll('.swiper-slide img, .gallery-item img');images=Array.from(galleryImages).map(img=>img.src);currentIndex=images.indexOf(imageSrc);if(currentIndex===-1)return console.error("⚠️ Immagine non trovata.");const modal=bootstrap.Modal.getOrCreateInstance(modalElement);modalImage.src=imageSrc;modal.show();};window.prevImage=()=>{images.length&&(currentIndex=currentIndex>0?currentIndex-1:images.length-1,document.getElementById("modalImage").src=images[currentIndex]);};window.nextImage=()=>{images.length&&(currentIndex=currentIndex<images.length-1?currentIndex+1:0,document.getElementById("modalImage").src=images[currentIndex]);};requestIdleCallback(()=>{document.querySelectorAll(".swiper-container").forEach(swiperEl=>{new Swiper(swiperEl,{slidesPerView:1,spaceBetween:10,loop:!0,autoplay:{delay:3e3,disableOnInteraction:!1},speed:1e3,navigation:{nextEl:swiperEl.querySelector('.swiper-button-next'),prevEl:swiperEl.querySelector('.swiper-button-prev')},pagination:{el:swiperEl.querySelector('.swiper-pagination'),clickable:!0},breakpoints:{768:{slidesPerView:3,slidesPerGroup:1}}})})})});window.acceptCookies=()=>{const banner=document.getElementById('cookie-banner');localStorage.setItem('cookiesAccepted','true');banner&&(banner.style.display='none');};const banner=document.getElementById('cookie-banner');banner&&localStorage.getItem('cookiesAccepted')==='true'&&(banner.style.display='none');
